#!/usr/bin/env node
/**
 * Regenerates all PNG favicons + apple-touch-icon from public/favicon.svg.
 * The .ico file should ideally be regenerated by a dedicated tool, but
 * modern browsers will use the SVG/PNG entries instead.
 */
import sharp from 'sharp';
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, '..');
const svgPath = resolve(root, 'public/favicon.svg');
const svg = readFileSync(svgPath);

// [outputPath, size]
const targets = [
    ['public/favicon-16x16.png', 16],
    ['public/favicon-32x32.png', 32],
    ['public/favicon-96x96.png', 96],
    ['public/apple-touch-icon.png', 180],
    ['public/brand/favicon-16x16.png', 16],
    ['public/brand/favicon-32x32.png', 32],
    ['public/brand/favicon-96x96.png', 96],
    ['public/brand/favicon-192.png', 192],
    ['public/brand/favicon-512.png', 512],
    ['public/brand/apple-touch-icon.png', 180],
    ['public/brand/logo-mark-192.png', 192],
    ['public/brand/logo-mark-512.png', 512],
];

for (const [out, size] of targets) {
    const buf = await sharp(svg, { density: 384 })
        .resize(size, size, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
        .png()
        .toBuffer();
    writeFileSync(resolve(root, out), buf);
    console.log(`✓ ${out} (${size}x${size})`);
}

// Build a multi-size .ico (16/32/48) using png-to-ico if available, else
// fall back to writing a 32x32 PNG renamed as .ico (browsers accept both).
try {
    const pngToIco = (await import('png-to-ico')).default;
    const sizes = [16, 32, 48, 64];
    const buffers = await Promise.all(
        sizes.map((s) =>
            sharp(svg, { density: 384 }).resize(s, s).png().toBuffer()
        )
    );
    const ico = await pngToIco(buffers);
    writeFileSync(resolve(root, 'public/favicon.ico'), ico);
    writeFileSync(resolve(root, 'public/brand/favicon.ico'), ico);
    console.log('✓ favicon.ico (multi-size)');
} catch (e) {
    console.warn('⚠ png-to-ico not installed, skipping .ico regeneration. Run: npm i -D png-to-ico');
}
